import { Database } from "bun:sqlite";
import { drizzle, type BunSQLiteDatabase } from "drizzle-orm/bun-sqlite";

import type { AppConfig } from "../config";
import * as schema from "./schema";

export type Schema = typeof schema;
export type DrizzleDb = BunSQLiteDatabase<Schema>;

export type Connection = {
  db: DrizzleDb;
  /** live database file path — used by the backup store method */
  dbPath: string;
  /** WAL checkpoint, so a straight file copy of the db is consistent */
  checkpoint(): void;
  close(): void;
};

export function openConnection(config: AppConfig): Connection {
  const driver = config.db.driver;

  if (driver === "sqlite") {
    const sqlite = new Database(config.db.path, { create: true });
    sqlite.exec("PRAGMA journal_mode = WAL;");
    sqlite.exec("PRAGMA foreign_keys = ON;");
    const db = drizzle(sqlite, { schema });
    return {
      db,
      dbPath: config.db.path,
      checkpoint() {
        sqlite.exec("PRAGMA wal_checkpoint(TRUNCATE);");
      },
      close() {
        sqlite.close();
      },
    };
  }

  // Postgres adapter lands here later — same StorePort, same callers (ADR-0003).
  throw new Error(
    `Unknown database driver "${driver}". Supported today: "sqlite". ` +
      "Swap via DOKAN_DB_DRIVER; procedures and use cases do not change.",
  );
}=====CONFIG=====
import path from "node:path";

export type AppConfig = {
  host: string;
  port: number;
  /** root folder holding the SQLite data file, the backups/ and logs/ folders */
  dataDir: string;
  /** MVP password-reset secret (per docs/adr + last grilling round). Env-overridable. */
  buildSecret: string;
  version: string;
  /** persistence driver selection — the store port stays fixed (ADR-0003) */
  db: {
    driver: "sqlite";
    /** database file path (sqlite) */
    path: string;
  };
};

export function createAppConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const dataDir = env.DOKAN_DATA_DIR ?? path.join(process.cwd(), "data");
  return {
    host: env.DOKAN_HOST ?? "127.0.0.1",
    port: Number(env.DOKAN_PORT ?? 4317),
    dataDir,
    buildSecret: env.DOKAN_BUILD_SECRET ?? "dokan-dev-secret",
    version: "0.1.0",
    db: {
      driver: "sqlite",
      path: env.DOKAN_DB_PATH ?? path.join(dataDir, "dokan.db"),
    },
  };
}

